import static org.junit.jupiter.api.Assertions.assertEquals;

import org.junit.jupiter.api.Test;

public class RestaurantTest {

    private final Restaurant restaurant = new Restaurant();

    @Test
    void returnsMildForLevelOne() {
        assertEquals("Mild", restaurant.getSpiceLevel(1));
    }

    @Test
    void returnsSpicyForLevelFive() {
        assertEquals("Spicy", restaurant.getSpiceLevel(5));
    }

    @Test
    void returnsEveryLabelInTheMiddleOfTheRange() {
        assertEquals("Medium-Mild", restaurant.getSpiceLevel(2));
        assertEquals("Medium", restaurant.getSpiceLevel(3));
        assertEquals("Medium-Spicy", restaurant.getSpiceLevel(4));
    }

    @Test
    void rejectsLevelsOutsideOneThroughFive() {
        assertEquals("Invalid spice level", restaurant.getSpiceLevel(0));
        assertEquals("Invalid spice level", restaurant.getSpiceLevel(6));
        assertEquals("Invalid spice level", restaurant.getSpiceLevel(-3));
    }
}
